import 'package:flutter/material.dart';

import '../../data/models/app_notification.dart';
import '../../l10n/generated/app_localizations.dart';
import 'notification_controller.dart';

/// Opens the inbox as a responsive dialog.
Future<void> showNotificationInbox(
  BuildContext context,
  NotificationController controller,
) {
  return showDialog<void>(
    context: context,
    builder: (context) => NotificationInbox(controller: controller),
  );
}

/// Notification list with per-item and bulk read actions.
class NotificationInbox extends StatelessWidget {
  const NotificationInbox({super.key, required this.controller});

  final NotificationController controller;

  @override
  Widget build(BuildContext context) {
    final l10n = AppLocalizations.of(context);
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;

    return Dialog(
      insetPadding: const EdgeInsets.all(20),
      child: ConstrainedBox(
        constraints: const BoxConstraints(maxWidth: 480, maxHeight: 580),
        child: AnimatedBuilder(
          animation: controller,
          builder: (context, _) {
            final items = controller.items;
            return Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Padding(
                  padding: const EdgeInsets.fromLTRB(20, 16, 8, 8),
                  child: Row(
                    children: [
                      Icon(
                        Icons.notifications_active_outlined,
                        color: scheme.primary,
                      ),
                      const SizedBox(width: 10),
                      Expanded(
                        child: Text(
                          l10n.notifications,
                          style: theme.textTheme.titleMedium?.copyWith(
                            fontWeight: FontWeight.w700,
                          ),
                        ),
                      ),
                      if (controller.unreadCount > 0)
                        Padding(
                          padding: const EdgeInsets.only(right: 4),
                          child: Text(
                            l10n.unreadCount(controller.unreadCount),
                            style: theme.textTheme.labelSmall?.copyWith(
                              color: scheme.primary,
                            ),
                          ),
                        ),
                      IconButton(
                        tooltip: l10n.close,
                        onPressed: () => Navigator.of(context).pop(),
                        icon: const Icon(Icons.close_rounded),
                      ),
                    ],
                  ),
                ),
                Divider(height: 1, color: scheme.outlineVariant),
                Expanded(
                  child: items.isEmpty
                      ? Center(
                          child: Padding(
                            padding: const EdgeInsets.all(24),
                            child: Column(
                              mainAxisSize: MainAxisSize.min,
                              children: [
                                Icon(
                                  Icons.check_circle_outline_rounded,
                                  size: 40,
                                  color: scheme.primary,
                                ),
                                const SizedBox(height: 10),
                                Text(l10n.noNotifications),
                              ],
                            ),
                          ),
                        )
                      : ListView.separated(
                          padding: const EdgeInsets.symmetric(vertical: 6),
                          itemCount: items.length,
                          separatorBuilder: (_, _) => Divider(
                            height: 1,
                            indent: 20,
                            endIndent: 20,
                            color: scheme.outlineVariant.withValues(alpha: 0.5),
                          ),
                          itemBuilder: (context, index) {
                            final item = items[index];
                            return _NotificationTile(
                              item: item,
                              onTap: () => controller.markRead(item.id),
                            );
                          },
                        ),
                ),
                Divider(height: 1, color: scheme.outlineVariant),
                Padding(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 12,
                    vertical: 8,
                  ),
                  child: Row(
                    children: [
                      TextButton(
                        onPressed: controller.unreadCount == 0
                            ? null
                            : controller.markAllRead,
                        child: Text(l10n.markAllRead),
                      ),
                      const Spacer(),
                      TextButton(
                        onPressed: items.any((item) => item.isRead)
                            ? controller.clearRead
                            : null,
                        child: Text(l10n.clearRead),
                      ),
                    ],
                  ),
                ),
              ],
            );
          },
        ),
      ),
    );
  }
}

class _NotificationTile extends StatelessWidget {
  const _NotificationTile({required this.item, required this.onTap});

  final AppNotification item;
  final VoidCallback onTap;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;
    final color = switch (item.severity) {
      NotificationSeverity.critical => scheme.error,
      NotificationSeverity.warning => const Color(0xFFE0A100),
      NotificationSeverity.info => scheme.primary,
    };
    final icon = switch (item.severity) {
      NotificationSeverity.critical => Icons.dangerous_outlined,
      NotificationSeverity.warning => Icons.warning_amber_rounded,
      NotificationSeverity.info => Icons.info_outline_rounded,
    };

    return ListTile(
      onTap: onTap,
      selected: !item.isRead,
      selectedTileColor: scheme.primary.withValues(alpha: 0.06),
      leading: Icon(icon, color: color, size: 22),
      title: Text(
        item.title,
        style: theme.textTheme.bodyMedium?.copyWith(
          fontWeight: item.isRead ? FontWeight.w500 : FontWeight.w700,
        ),
      ),
      subtitle: Padding(
        padding: const EdgeInsets.only(top: 2),
        child: Text(
          item.message,
          style: theme.textTheme.bodySmall?.copyWith(
            color: scheme.onSurfaceVariant,
          ),
        ),
      ),
      trailing: Text(
        _time(item.createdAt.toLocal()),
        style: theme.textTheme.labelSmall?.copyWith(
          color: scheme.onSurfaceVariant,
        ),
      ),
    );
  }

  String _time(DateTime time) {
    final now = DateTime.now();
    final sameDay =
        now.year == time.year && now.month == time.month && now.day == time.day;
    final hh = time.hour.toString().padLeft(2, '0');
    final mm = time.minute.toString().padLeft(2, '0');
    if (sameDay) {
      return '$hh:$mm';
    }
    final dd = time.day.toString().padLeft(2, '0');
    final mo = time.month.toString().padLeft(2, '0');
    return '$dd/$mo';
  }
}
